export const CREATE_TABLE_METADATA_ATTRIBUTE = `
    CREATE TABLE Metadata__Attribute(
        EntityId UniqueIdentifier, 
        AttributeId UniqueIdentifier PRIMARY KEY, 
        LogicalName string, 
        AttributeType int,
        DefaultFormValue int NULL,
        OptionSetId UniqueIdentifier,
        AttributeOf string NULL,
        AttributeTypeName string
    )
`;
export const INSERT_METADATA_ATTRIBUTE = `
    INSERT INTO Metadata__Attribute VALUES (
        ?,
        ?,
        ?,
        ?,
        ?,
        ?,
        ?,
        ?
    )
`;
export const SELECT_METADATA_ATTRIBUTE = `
    SELECT
        E.LogicalName as EntityLogicalName, 
        AttributeId, 
        A.LogicalName as LogicalName, 
        AttributeType,
        DefaultFormValue,
        OptionSetId,
        AttributeOf,
        AttributeTypeName
    FROM 
        Metadata__Attribute A 
            INNER JOIN
        Metadata__Entity E ON A.EntityId=E.EntityId
    WHERE A.LogicalName = ? AND E.LogicalName = ?
`;
export const SELECT_METADATA_ATTRIBUTE_BY_ID = `
    SELECT
        E.LogicalName as EntityLogicalName, 
        AttributeId, 
        A.LogicalName as LogicalName, 
        AttributeType,
        DefaultFormValue,
        OptionSetId,
        AttributeOf,
        AttributeTypeName
    FROM 
        Metadata__Attribute A 
            INNER JOIN
        Metadata__Entity E ON A.EntityId=E.EntityId
    WHERE A.AttributeId = ?
`;
export const SELECT_METADATA_ATTRIBUTES = `
    SELECT
        E.LogicalName as EntityLogicalName, 
        AttributeId, 
        A.LogicalName as LogicalName, 
        AttributeType,
        DefaultFormValue,
        OptionSetId,
        AttributeOf,
        AttributeTypeName
    FROM 
        Metadata__Attribute AS A 
            INNER JOIN
        Metadata__Entity AS E ON A.EntityId=E.EntityId
    WHERE E.LogicalName = ?
`;
export class AttributeMetadataSQL {
  constructor(sql) {
    this.sql = void 0;
    this.sql = sql;
    sql(CREATE_TABLE_METADATA_ATTRIBUTE);
  }
  AddAttributeMetadata(metadata) {
    this.sql(INSERT_METADATA_ATTRIBUTE, [metadata.EntityId, metadata.AttributeId, metadata.LogicalName, metadata.AttributeType, metadata.DefaultFormValue, metadata.OptionSetId, metadata.AttributeOf, metadata.AttributeTypeName]);
  }
  SelectAttributeMetadata(AttributeLogicalName, EntityLogicalName) {
    return this.sql(SELECT_METADATA_ATTRIBUTE, [AttributeLogicalName, EntityLogicalName]);
  }
  SelectAttributeMetadataById(AttributeId) {
    return this.sql(SELECT_METADATA_ATTRIBUTE, [AttributeId]);
  }
  SelectAttributeMetadataForTable(EntityLogicalName) {
    return this.sql(SELECT_METADATA_ATTRIBUTES, [EntityLogicalName]);
  }
}