import { stub } from 'sinon';
export class EntityRecordMock {
  constructor(db, etn, id, updateView) {
    this._db = void 0;
    this._boundRow = void 0;
    this._boundTable = void 0;
    this._isDirty = void 0;
    this._isValid = void 0;
    this._updateView = void 0;
    this.getFormattedValue = void 0;
    this.getRecordId = void 0;
    this.getValue = void 0;
    this.getNamedReference = void 0;
    this.isDirty = void 0;
    this.isValid = void 0;
    this.save = void 0;
    this.setValue = void 0;
    this._updateView = updateView;
    this._db = db;
    this._boundTable = etn;
    this._boundRow = id;
    this._isDirty = false;
    this._isValid = true;
    this.getFormattedValue = stub();
    this.getFormattedValue.callsFake(columnName => {
      const {
        value,
        attributeMetadata
      } = this._db.GetValueAndMetadata(this._boundTable, columnName, this._boundRow);
      return value === undefined ? value : '' + value;
    });
    this.getNamedReference = stub();
    this.getNamedReference.callsFake(() => {
      const {
        row,
        entityMetadata
      } = this._db.GetRow(this._boundTable, this._boundRow);
      if (!row) {
        return {
          id: {
            guid: ''
          },
          name: ''
        };
      }
      const id = {
        guid: row?.[entityMetadata ? entityMetadata.PrimaryIdAttribute || entityMetadata.LogicalName + 'id' : 'id']
      };
      const etn = entityMetadata?.LogicalName;
      const name = row?.[entityMetadata?.PrimaryNameAttribute || 'name'];
      return {
        id,
        etn,
        name
      };
    });
    this.getRecordId = stub();
    this.getRecordId.callsFake(() => id);
    this.getValue = stub();
    this.getValue.callsFake(columnName => {
      const {
        value,
        attributeMetadata
      } = this._db.GetValueAndMetadata(this._boundTable, columnName, this._boundRow);
      return value;
    });
    this.isDirty = stub();
    this.isDirty.callsFake(() => this._isDirty);
    this.isValid = stub();
    this.isValid.callsFake(() => this._isValid);
    this.save = stub();
    this.save.callsFake(() => {
      return new Promise(resolve => {
        setTimeout(() => {
          this._isDirty = false;
          if (this._updateView) {
            this._updateView();
          }
          resolve();
        }, 10);
      });
    });
    this.setValue = stub();
    this.setValue.callsFake((columnName, value) => {
      return new Promise(resolve => {
        setTimeout(() => {
          this._db.UpdateValue(value, this._boundTable, columnName, this._boundRow);
          this._isDirty = true;
          if (this._updateView) {
            this._updateView();
          }
          resolve();
        }, 10);
      });
    });
  }
}